(()=>{const p=figma.getNodeById('4:2');const C={ink:'#202332',muted:'#7B7E8C',line:'#EEEFF4',soft:'#F6F5FA',brand:'#684DEC',tint:'#F0ECFF'};const rgb=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});const fill=h=>[{type:'SOLID',color:rgb(h)}];const assets={};for(const id of ['1:3','1:4'])for(const n of figma.getNodeById(id).findAll(n=>n.type==='COMPONENT'))assets[n.name]=n;const lib={};for(const c of p.children.filter(n=>n.type==='COMPONENT'))lib[c.name]=c;
function box(pa,x,y,w,h,col='#FFFFFF',r=0,name='Surface'){let n=figma.createFrame();n.name=name;n.resize(w,h);pa.appendChild(n);n.x=x;n.y=y;n.fills=fill(col);n.cornerRadius=r;return n;}function text(pa,s,x,y,w,size=14,weight='Regular',col=C.ink){let n=figma.createText();pa.appendChild(n);n.fontName={family:'Inter',style:weight};n.characters=s;n.fontSize=size;n.lineHeight={unit:'PERCENT',value:145};n.fills=fill(col);n.resize(w,10);n.textAutoResize='HEIGHT';n.x=x;n.y=y;return n;}function asset(pa,name,x,y,w,h){let n=assets[name].createInstance();pa.appendChild(n);n.x=x;n.y=y;if(w)n.resize(w,h||w);return n;}function photo(pa,name,x,y,w,h,r=14){let n=asset(pa,name,x,y,w,h);n.cornerRadius=r;return n;}function inst(pa,c,x,y){let n=(typeof c==='string'?lib[c]:c).createInstance();pa.appendChild(n);n.x=x;n.y=y;return n;}function btn(pa,s,y){let n=asset(pa,'Button',16,y);n.name=s;n.findOne(n=>n.type==='TEXT').characters=s;return n;}function linktext(pa,s,x,y,w=150){return text(pa,s,x,y,w,13,'Semi Bold',C.brand);}function screen(name,i,h=812){let n=box(p,(i%4)*445,Math.floor(i/4)*2600,375,h,'#FFFFFF',0,name);n.clipsContent=true;asset(n,'Status Bar',0,0);asset(n,'Home Indicator',0,h-34);return n;}function header(n,title){asset(n,'Icon_Arrow_Left',20,60);text(n,title,58,56,265,19,'Semi Bold');}function field(n,label,value,y,icon){let f=asset(n,'Text Field',16,y);let ts=f.findAll(n=>n.type==='TEXT');ts[0].characters=label;ts[1].characters=value;if(icon){let input=f.findOne(n=>n.name==='Input');for(const ch of input.children)if(ch.type!=='TEXT')ch.visible=false;asset(n,icon,30,y+36,22,22);}return f;}function component(name,w,h){let c=figma.createComponent();p.appendChild(c);c.name=name;c.resize(w,h);c.x=1900;c.y=Object.keys(lib).length*360;c.fills=fill('#FFFFFF');lib[name]=c;return c;}
function search(n,y=60,value){let s=inst(n,'Search',16,y);s.name='Go Filter';if(value)s.findOne(n=>n.type==='TEXT').characters=value;return s;}function tabs(n,current,y=n.height-100){let b=inst(n,'Tab bar',0,y);for(let cell of b.children){if(cell.name===current){cell.fills=fill(C.tint);cell.findOne(n=>n.type==='TEXT').fills=fill(C.brand);}}return b;}function title(n,s,y,sub){text(n,s,16,y,285,19,'Semi Bold');linktext(n,'See all',307,y+4,55);if(sub)text(n,sub,16,y+30,300,12,'Regular',C.muted);}function card(pa,x,y,a,t,loc,rate,price,rooms='2 room   ·   673 m²'){let n=inst(pa,'Property card',x,y);n.name=t;let im=n.findOne(n=>n.type==='INSTANCE'&&n.mainComponent?.name==='Photo_Bromo_Cabin');im.swapComponent(assets[a]);let ts=n.findAll(n=>n.type==='TEXT');[rate,t,loc,rooms,price].forEach((s,i)=>ts[i].characters=s);return n;}function dest(pa,x,y,a,t,sub){let n=inst(pa,'Destination card',x,y);n.findOne(n=>n.type==='INSTANCE').swapComponent(assets[a]);let ts=n.findAll(n=>n.type==='TEXT');ts[0].characters=t;ts[1].characters=sub;return n;}function rail(n,y,data){let f=box(n,16,y,359,310,'#FFFFFF',0,'Horizontal property rail');f.clipsContent=true;f.overflowDirection='HORIZONTAL';data.forEach((d,i)=>card(f,i*280,0,...d));return f;}function chip(n,s,x,y,w=100,sel=false){let c=box(n,x,y,w,34,sel?C.tint:C.soft,9,'Choice · '+s);text(c,s,10,8,w-16,12,sel?'Semi Bold':'Medium',sel?C.brand:C.muted);return c;}function divider(n,y){box(n,16,y,343,1,C.line);}const bromo=['Photo_Bromo_Cabin','Entire Bromo mountain view Cabin in Surabaya','Malang, Probolinggo','4.8 (73)','$1,290 / month'];return {p,C,fill,assets,lib,box,text,asset,photo,inst,btn,linktext,screen,header,field,component,search,tabs,title,card,dest,rail,chip,divider,bromo};})()

